/**
 * RPC contract tests: stripe_tax_registration_record (S19)
 *
 * Coverage (5 tests):
 *  1. Happy path inserts with status='active', returns { id, created: true }
 *  2. Idempotency on (studio_id, registration_id) UNIQUE: returns same id, created: false on replay
 *  3. Status update: re-call with changed status updates row
 *  4. Invalid status enum: RAISE EXCEPTION
 *  5. studio_id FK CASCADE: delete studio → registration row gone
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  type StripeTaxRegistrationRecordArgs,
  type StripeTaxRegistrationRecordResult,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: stripe_tax_registration_record', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string

  beforeAll(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
  })

  afterAll(async () => {
    await cleanupStudio(studioId)
  })

  function buildArgs(
    overrides: Partial<StripeTaxRegistrationRecordArgs> = {},
  ): StripeTaxRegistrationRecordArgs {
    return {
      studioId,
      registrationId: `txr_${randomUUID().replace(/-/g, '').slice(0, 20)}`,
      country: 'US',
      state: 'NY',
      jurisdiction: 'US-NY',
      status: 'active',
      activeFrom: '2026-01-01',
      activeUntil: null,
      ...overrides,
    }
  }

  function rpcArgs(args: StripeTaxRegistrationRecordArgs) {
    return {
      p_studio_id: args.studioId,
      p_registration_id: args.registrationId,
      p_country: args.country,
      p_state: args.state,
      p_jurisdiction: args.jurisdiction,
      p_status: args.status,
      p_active_from: args.activeFrom,
      p_active_until: args.activeUntil,
    }
  }

  it('happy path — inserts with status=active, returns { id, created: true }', async () => {
    const args = buildArgs()

    const { data, error } = await sb.rpc(RPC.STRIPE_TAX_REGISTRATION_RECORD, rpcArgs(args))

    expect(error).toBeNull()
    const result = data as StripeTaxRegistrationRecordResult
    expect(result.created).toBe(true)
    expect(result.id).toBeTruthy()
    expect(result.id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/,
    )

    // Verify status in DB
    const { data: row } = await sb
      .from('stripe_tax_registrations')
      .select('status, jurisdiction')
      .eq('id', result.id)
      .maybeSingle()

    expect(row?.status).toBe('active')
    expect(row?.jurisdiction).toBe('US-NY')
  })

  it('idempotency on (studio_id, registration_id) UNIQUE — replay returns same id, created: false', async () => {
    const args = buildArgs({
      registrationId: `txr_idem_${randomUUID().replace(/-/g, '').slice(0, 16)}`,
      jurisdiction: 'US-CA',
      state: 'CA',
    })
    const params = rpcArgs(args)

    const { data: first, error: e1 } = await sb.rpc(RPC.STRIPE_TAX_REGISTRATION_RECORD, params)
    expect(e1).toBeNull()
    const firstResult = first as StripeTaxRegistrationRecordResult
    expect(firstResult.created).toBe(true)

    const { data: second, error: e2 } = await sb.rpc(RPC.STRIPE_TAX_REGISTRATION_RECORD, params)
    expect(e2).toBeNull()
    const secondResult = second as StripeTaxRegistrationRecordResult
    expect(secondResult.created).toBe(false)
    expect(secondResult.id).toBe(firstResult.id)
  })

  it('status update — re-call with changed status updates existing row', async () => {
    const registrationId = `txr_upd_${randomUUID().replace(/-/g, '').slice(0, 16)}`
    const args = buildArgs({ registrationId, status: 'active' })

    const { data: first, error: e1 } = await sb.rpc(
      RPC.STRIPE_TAX_REGISTRATION_RECORD,
      rpcArgs(args),
    )
    expect(e1).toBeNull()
    const firstResult = first as StripeTaxRegistrationRecordResult

    // Re-call with status='expired'
    const { data: second, error: e2 } = await sb.rpc(
      RPC.STRIPE_TAX_REGISTRATION_RECORD,
      rpcArgs({ ...args, status: 'expired', activeUntil: '2026-12-31' }),
    )
    expect(e2).toBeNull()
    const secondResult = second as StripeTaxRegistrationRecordResult
    expect(secondResult.id).toBe(firstResult.id)

    const { data: row } = await sb
      .from('stripe_tax_registrations')
      .select('status, active_until')
      .eq('id', firstResult.id)
      .maybeSingle()

    expect(row?.status).toBe('expired')
  })

  it('invalid status enum — RAISE EXCEPTION', async () => {
    const args = buildArgs()

    const { error } = await sb.rpc(RPC.STRIPE_TAX_REGISTRATION_RECORD, {
      ...rpcArgs(args),
      p_status: 'invalid_status_xyz',
    })

    expect(error).not.toBeNull()
  })

  it('studio_id FK CASCADE — delete studio removes registration row', async () => {
    // Create a disposable studio so CASCADE delete doesn't break the suite fixture
    const { createTestStudio: makeStudio } = await import('./helpers')
    const tempStudio = await makeStudio()

    const args = buildArgs({ studioId: tempStudio.id })

    const { data, error } = await sb.rpc(RPC.STRIPE_TAX_REGISTRATION_RECORD, rpcArgs(args))
    expect(error).toBeNull()
    const result = data as StripeTaxRegistrationRecordResult
    expect(result.created).toBe(true)
    const rowId = result.id

    // Cascade delete
    await sb.from('studios').delete().eq('id', tempStudio.id)

    const { data: row } = await sb
      .from('stripe_tax_registrations')
      .select('id')
      .eq('id', rowId)
      .maybeSingle()

    expect(row).toBeNull()
  })
})

/**
 * RPC contract tests: stripe_tax_registration_remove (S19)
 *
 * Coverage (3 tests):
 *  1. Happy path: status flips to 'expired'
 *  2. Re-call on already-expired: idempotent
 *  3. Missing registration_id: RAISE EXCEPTION
 */

