/**
 * RPC contract tests: tax_oss_quarterly_export (S19)
 *
 * Coverage (6 tests):
 *  1. Empty: returns jurisdictions: [], totals 0
 *  2. Multi-EU jurisdictions (DE+FR+IT) all returned with correct sums
 *  3. registration_status join: active registration → 'active'; no registration → null
 *  4. Quarter math: Q1 2026 includes only entries with period='2026-Q1'
 *  5. Outstanding = collected - remitted (seeded via TAX_REMITTANCE_FILE)
 *  6. total_eu_collected_cents = sum of all returned jurisdictions
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { randomUUID } from 'crypto'
import {
  hasDb,
  getTestServiceClient,
  createTestStudio,
  createTestLocation,
  cleanupStudio,
} from './helpers'
import {
  RPC,
  cents,
  type TaxOssQuarterlyExportResult,
  type TaxRemittanceAccrueResult,
  type TaxRemittanceFileResult,
  type StripeTaxRegistrationRecordResult,
} from '@/lib/payments/contracts'

describe.skipIf(!hasDb)('RPC: tax_oss_quarterly_export', () => {
  let sb: Awaited<ReturnType<typeof getTestServiceClient>>
  let studioId: string
  let locationId: string

  beforeAll(async () => {
    sb = await getTestServiceClient()
    const studio = await createTestStudio()
    studioId = studio.id
    const location = await createTestLocation(studioId)
    locationId = location.id
  })

  afterAll(async () => {
    await cleanupStudio(studioId)
  })

  async function accrue(jurisdiction: string, period: string, amountCents: number): Promise<string> {
    const { data, error } = await sb.rpc(RPC.TAX_REMITTANCE_ACCRUE, {
      p_studio_id: studioId,
      p_location_id: locationId,
      p_jurisdiction: jurisdiction,
      p_period: period,
      p_amount_collected_cents: cents(amountCents),
    })
    if (error) throw new Error(`accrue failed (${jurisdiction} ${period}): ${error.message}`)
    return (data as TaxRemittanceAccrueResult).id
  }

  async function fileRemittance(ledgerId: string, amountCents: number): Promise<void> {
    const { error } = await sb.rpc(RPC.TAX_REMITTANCE_FILE, {
      p_ledger_id: ledgerId,
      p_amount_remitted_cents: cents(amountCents),
      p_remittance_date: '2026-04-15',
      p_remittance_reference: `REF-${ledgerId.slice(0, 8)}`,
    })
    if (error) throw new Error(`fileRemittance failed: ${error.message}`)
  }

  async function seedRegistration(jurisdiction: string, registrationId: string): Promise<void> {
    const { error } = await sb.rpc(RPC.STRIPE_TAX_REGISTRATION_RECORD, {
      p_studio_id: studioId,
      p_registration_id: registrationId,
      p_country: jurisdiction.slice(3, 5), // 'EU-DE' → 'DE'
      p_state: null,
      p_jurisdiction: jurisdiction,
      p_status: 'active',
      p_active_from: '2026-01-01',
      p_active_until: null,
    })
    if (error) throw new Error(`seedRegistration failed: ${error.message}`)
  }

  function exportArgs(year: number, quarter: 1 | 2 | 3 | 4) {
    return {
      p_studio_id: studioId,
      p_year: year,
      p_quarter: quarter,
    }
  }

  it('empty — returns jurisdictions: [], totals 0', async () => {
    // Use a fresh studio with no data
    const { createTestStudio: makeStudio } = await import('./helpers')
    const emptyStudio = await makeStudio()

    const { data, error } = await sb.rpc(RPC.TAX_OSS_QUARTERLY_EXPORT, {
      p_studio_id: emptyStudio.id,
      p_year: 2026,
      p_quarter: 1,
    })

    // Cleanup
    await sb.from('studios').delete().eq('id', emptyStudio.id)

    expect(error).toBeNull()
    const result = data as TaxOssQuarterlyExportResult
    expect(result.jurisdictions).toHaveLength(0)
    expect(result.total_eu_collected_cents).toBe(0)
    expect(result.total_eu_outstanding_cents).toBe(0)
  })

  it('multi-EU jurisdictions (DE+FR+IT) — all returned with correct sums', async () => {
    const period = `2026-Q2-oss-multi-${randomUUID().slice(0, 4)}`
    // We'll use a period that maps to Q2 in the export RPC
    // Seed each EU jurisdiction
    await accrue('EU-DE', '2026-Q2', 10000)
    await accrue('EU-FR', '2026-Q2', 8000)
    await accrue('EU-IT', '2026-Q2', 6000)

    const { data, error } = await sb.rpc(RPC.TAX_OSS_QUARTERLY_EXPORT, exportArgs(2026, 2))

    expect(error).toBeNull()
    const result = data as TaxOssQuarterlyExportResult
    const jurisdictions = result.jurisdictions.map((j) => j.jurisdiction)

    expect(jurisdictions).toContain('EU-DE')
    expect(jurisdictions).toContain('EU-FR')
    expect(jurisdictions).toContain('EU-IT')

    const de = result.jurisdictions.find((j) => j.jurisdiction === 'EU-DE')
    const fr = result.jurisdictions.find((j) => j.jurisdiction === 'EU-FR')
    const it = result.jurisdictions.find((j) => j.jurisdiction === 'EU-IT')

    expect(de?.amount_collected_cents).toBeGreaterThanOrEqual(10000)
    expect(fr?.amount_collected_cents).toBeGreaterThanOrEqual(8000)
    expect(it?.amount_collected_cents).toBeGreaterThanOrEqual(6000)
  })

  it('registration_status join: active registration → active; no registration → null', async () => {
    // Seed EU-NL with registration
    await accrue('EU-NL', '2026-Q3', 5000)
    const regId = `txr_oss_nl_${randomUUID().replace(/-/g, '').slice(0, 14)}`
    await seedRegistration('EU-NL', regId)

    // Seed EU-BE without registration
    await accrue('EU-BE', '2026-Q3', 3000)

    const { data, error } = await sb.rpc(RPC.TAX_OSS_QUARTERLY_EXPORT, exportArgs(2026, 3))

    expect(error).toBeNull()
    const result = data as TaxOssQuarterlyExportResult

    const nl = result.jurisdictions.find((j) => j.jurisdiction === 'EU-NL')
    const be = result.jurisdictions.find((j) => j.jurisdiction === 'EU-BE')

    if (nl) {
      expect(nl.registration_status).toBe('active')
    }
    if (be) {
      expect(be.registration_status).toBeNull()
    }
  })

  it('quarter math: Q1 2026 includes only entries with period=2026-Q1', async () => {
    // Seed Q1 entry
    await accrue('EU-ES', '2026-Q1', 7500)
    // Seed Q4 entry — must NOT appear in Q1 export
    await accrue('EU-ES', '2026-Q4', 9999)

    const { data: q1Data, error: q1Err } = await sb.rpc(
      RPC.TAX_OSS_QUARTERLY_EXPORT,
      exportArgs(2026, 1),
    )
    expect(q1Err).toBeNull()
    const q1Result = q1Data as TaxOssQuarterlyExportResult

    const { data: q4Data, error: q4Err } = await sb.rpc(
      RPC.TAX_OSS_QUARTERLY_EXPORT,
      exportArgs(2026, 4),
    )
    expect(q4Err).toBeNull()
    const q4Result = q4Data as TaxOssQuarterlyExportResult

    const esInQ1 = q1Result.jurisdictions.find((j) => j.jurisdiction === 'EU-ES')
    const esInQ4 = q4Result.jurisdictions.find((j) => j.jurisdiction === 'EU-ES')

    // Q1 sum should include 7500 (and no Q4 contamination)
    if (esInQ1) {
      expect(esInQ1.amount_collected_cents).toBeGreaterThanOrEqual(7500)
    }
    // Q4 sum should include 9999 (and no Q1 contamination)
    if (esInQ4) {
      expect(esInQ4.amount_collected_cents).toBeGreaterThanOrEqual(9999)
    }

    // Q1 result must not have Q4's 9999 in EU-ES total
    if (esInQ1 && esInQ4) {
      expect(esInQ1.amount_collected_cents).not.toBe(esInQ4.amount_collected_cents)
    }
  })

  it('outstanding = collected - remitted (seeded via TAX_REMITTANCE_FILE)', async () => {
    const collected = 12000
    const remitted = 4000
    const expected_outstanding = collected - remitted

    const ledgerId = await accrue('EU-PT', '2026-Q2', collected)
    await fileRemittance(ledgerId, remitted)

    const { data, error } = await sb.rpc(RPC.TAX_OSS_QUARTERLY_EXPORT, exportArgs(2026, 2))

    expect(error).toBeNull()
    const result = data as TaxOssQuarterlyExportResult

    const pt = result.jurisdictions.find((j) => j.jurisdiction === 'EU-PT')
    expect(pt).toBeDefined()
    if (pt) {
      expect(pt.amount_collected_cents).toBeGreaterThanOrEqual(collected)
      expect(pt.amount_remitted_cents).toBeGreaterThanOrEqual(remitted)
      expect(pt.amount_outstanding_cents).toBeGreaterThanOrEqual(expected_outstanding)
    }
  })

  it('total_eu_collected_cents = sum of all returned jurisdictions', async () => {
    // Use Q3 which we haven't heavily polluted — check invariant holds for whatever is there
    const { data, error } = await sb.rpc(RPC.TAX_OSS_QUARTERLY_EXPORT, exportArgs(2026, 3))

    expect(error).toBeNull()
    const result = data as TaxOssQuarterlyExportResult

    const sumFromJurisdictions = result.jurisdictions.reduce(
      (acc, j) => acc + j.amount_collected_cents,
      0,
    )

    expect(result.total_eu_collected_cents).toBe(sumFromJurisdictions)
  })
})

