// ---------------------------------------------------------------------------
// Supabase mock factory
// ---------------------------------------------------------------------------

let capturedRpcCalls: Array<{ fn: string; args: Record<string, unknown> }> = []

function makeSupabaseMock(opts: {
  invoiceRecordError?: { message: string } | null
} = {}): SupabaseClient {
  const rpcMock = vi.fn(async (fn: string, args: Record<string, unknown>) => {
    capturedRpcCalls.push({ fn, args: args ?? {} })
    if (fn === RPC.STRIPE_INVOICE_RECORD) {
      if (opts.invoiceRecordError) return { data: null, error: opts.invoiceRecordError }
      return { data: { id: 'invoice-row-001', created: true }, error: null }
    }
    return { data: null, error: null }
  })

  return { rpc: rpcMock } as unknown as SupabaseClient
}

// ---------------------------------------------------------------------------
// Base args factory
// ---------------------------------------------------------------------------

function makeArgs(overrides: Partial<CreateSessionInvoiceArgs> = {}): CreateSessionInvoiceArgs {
  return {
    studioId: 'studio-s19-001',
    bookingId: '00000000-0000-4000-8000-000000000011',
    projectId: '00000000-0000-4000-8000-000000000012',
    sessionId: '00000000-0000-4000-8000-000000000013',
    artistId: '00000000-0000-4000-8000-000000000014',
    clientId: '00000000-0000-4000-8000-000000000015',
    customerId: 'cus_s19_test_001',
    paymentMethodId: 'pm_s19_test_001',
    currency: 'usd',
    baseAmountCents: cents(15000),
    tipAmountCents: cents(0),
    depositDrawdownCents: cents(0),
    applicationFeeCents: cents(4500),
    destinationAccount: 'acct_studio_s19_001',
    ...overrides,
  }
}

