function makeStripeInvoiceResponse(overrides: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    id: 'in_s19_test_001',
    status: 'paid',
    total: 15000,
    subtotal: 14000,
    tax: 1000,
    amount_paid: 15000,
    amount_due: 0,
