describe('createSessionInvoice — S19 invoice flow', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    capturedRpcCalls = []

    mockInvoicesCreate.mockResolvedValue(makeStripeInvoiceResponse())
    mockInvoiceItemsCreate.mockResolvedValue({ id: 'ii_test_001' })
    mockInvoicesFinalizeInvoice.mockResolvedValue(makeStripeInvoiceResponse())
    mockInvoicesPay.mockResolvedValue(makeStripeInvoiceResponse())
  })

  it('happy path: invoices.create + invoiceItems.create (base) + finalizeInvoice + pay + STRIPE_INVOICE_RECORD', async () => {
    const { createSessionInvoice } = await import('@/lib/stripe/invoices')
    const sb = makeSupabaseMock()

    const result = await createSessionInvoice(sb, makeArgs())

    expect(result.invoiceId).toBe('in_s19_test_001')
    expect(result.taxAmountCents).toBe(1000)
    expect(result.totalCents).toBe(15000)

    // Stripe call sequence
    expect(mockInvoicesCreate).toHaveBeenCalledOnce()
    expect(mockInvoiceItemsCreate).toHaveBeenCalledTimes(1) // base only (no tip, no drawdown)
    expect(mockInvoicesFinalizeInvoice).toHaveBeenCalledOnce()
    expect(mockInvoicesPay).toHaveBeenCalledOnce()

    // STRIPE_INVOICE_RECORD RPC called once
    const invoiceRecordCalls = capturedRpcCalls.filter((c) => c.fn === RPC.STRIPE_INVOICE_RECORD)
    expect(invoiceRecordCalls).toHaveLength(1)
    expect(invoiceRecordCalls[0]!.args['p_invoice_id']).toBe('in_s19_test_001')
    expect(invoiceRecordCalls[0]!.args['p_studio_id']).toBe('studio-s19-001')
  })

  it('INVARIANT 2: idempotency keys present on every Stripe call (request option + metadata.inkos_idempotency_key)', async () => {
    const { createSessionInvoice } = await import('@/lib/stripe/invoices')
    const sb = makeSupabaseMock()

    await createSessionInvoice(sb, makeArgs())

    // invoices.create — idempotency option + metadata
    expect(mockInvoicesCreate).toHaveBeenCalledOnce()
    const [invoiceBody, invoiceOpts] = mockInvoicesCreate.mock.calls[0] as [
      Record<string, unknown>,
      Record<string, unknown>,
    ]
    expect(typeof invoiceOpts?.['idempotencyKey']).toBe('string')
    expect(invoiceOpts?.['idempotencyKey']).toBeTruthy()
    const invoiceMeta = invoiceBody['metadata'] as Record<string, string>
    expect(invoiceMeta?.['inkos_idempotency_key']).toBeTruthy()
    expect(invoiceMeta?.['inkos_idempotency_key']).toBe(invoiceOpts?.['idempotencyKey'])

    // invoiceItems.create (base) — idempotency option
    expect(mockInvoiceItemsCreate).toHaveBeenCalled()
    const [, itemOpts] = mockInvoiceItemsCreate.mock.calls[0] as [
      Record<string, unknown>,
      Record<string, unknown>,
    ]
    expect(typeof itemOpts?.['idempotencyKey']).toBe('string')
    expect(itemOpts?.['idempotencyKey']).toBeTruthy()

    // finalizeInvoice — idempotency option
    const [, finalizeOpts] = mockInvoicesFinalizeInvoice.mock.calls[0] as [
      string,
      Record<string, unknown>,
      Record<string, unknown>,
    ]
    expect(finalizeOpts?.['idempotencyKey']).toBeTruthy()

    // pay — idempotency option
    const [, , payOpts] = mockInvoicesPay.mock.calls[0] as [
      string,
      Record<string, unknown>,
      Record<string, unknown>,
    ]
    expect(payOpts?.['idempotencyKey']).toBeTruthy()
  })

  it('INVARIANT 4: application_fee_amount set on invoice create — never undefined', async () => {
    const { createSessionInvoice } = await import('@/lib/stripe/invoices')
    const sb = makeSupabaseMock()

    await createSessionInvoice(sb, makeArgs({ applicationFeeCents: cents(3000) }))

    const [invoiceBody] = mockInvoicesCreate.mock.calls[0] as [Record<string, unknown>]
    expect(invoiceBody['application_fee_amount']).toBeDefined()
    expect(invoiceBody['application_fee_amount']).toBe(3000)
    expect(invoiceBody['application_fee_amount']).not.toBeUndefined()
  })

  it('automatic_tax: { enabled: true } passed on invoice create', async () => {
    const { createSessionInvoice } = await import('@/lib/stripe/invoices')
    const sb = makeSupabaseMock()

    await createSessionInvoice(sb, makeArgs())

    const [invoiceBody] = mockInvoicesCreate.mock.calls[0] as [Record<string, unknown>]
    const automaticTax = invoiceBody['automatic_tax'] as Record<string, unknown>
    expect(automaticTax).toBeDefined()
    expect(automaticTax?.['enabled']).toBe(true)
  })

  it('tip > 0: extra invoiceItems.create call for tip with inkos_line_kind=tip', async () => {
    const { createSessionInvoice } = await import('@/lib/stripe/invoices')
    const sb = makeSupabaseMock()

    await createSessionInvoice(sb, makeArgs({ tipAmountCents: cents(2000) }))

    // base + tip = 2 calls
    expect(mockInvoiceItemsCreate).toHaveBeenCalledTimes(2)

    const tipCall = mockInvoiceItemsCreate.mock.calls.find(([body]: [Record<string, unknown>]) => {
      const meta = body['metadata'] as Record<string, string>
      return meta?.['inkos_line_kind'] === 'tip'
    }) as [Record<string, unknown>, Record<string, unknown>] | undefined

    expect(tipCall).toBeDefined()
    expect(tipCall?.[0]['amount']).toBe(2000)
  })

  it('deposit drawdown > 0: negative-amount invoiceItems.create with inkos_line_kind=deposit_drawdown', async () => {
    const { createSessionInvoice } = await import('@/lib/stripe/invoices')
    const sb = makeSupabaseMock()

    await createSessionInvoice(sb, makeArgs({ depositDrawdownCents: cents(5000) }))

    // base + drawdown = 2 calls
    expect(mockInvoiceItemsCreate).toHaveBeenCalledTimes(2)

    const drawdownCall = mockInvoiceItemsCreate.mock.calls.find(
      ([body]: [Record<string, unknown>]) => {
        const meta = body['metadata'] as Record<string, string>
        return meta?.['inkos_line_kind'] === 'deposit_drawdown'
      },
    ) as [Record<string, unknown>, Record<string, unknown>] | undefined

    expect(drawdownCall).toBeDefined()
    // Amount must be negative (deposit applied reduces the invoice total)
    expect((drawdownCall?.[0]['amount'] as number)).toBeLessThan(0)
    expect(drawdownCall?.[0]['amount']).toBe(-5000)
  })
})

/**
 * Integration tests: POST /api/admin/tax-oss-export
 *
 * Supabase, auth, rate limit, and audit log fully mocked.
 * No DB required.
 *
 * Coverage (5 tests):
 *  1. No auth → 401
 *  2. Authenticated non-admin → 403
 *  3. Body validation: missing year or quarter → 400
 *  4. Happy path: 200, Content-Type: text/csv, Content-Disposition with filename, CSV header + rows + TOTAL footer
 *  5. Audit log called once on happy path
 */

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { NextRequest } from 'next/server'
import { RPC, type TaxOssQuarterlyExportResult } from '@/lib/payments/contracts'

// ---------------------------------------------------------------------------
// Mock Supabase server client
// ---------------------------------------------------------------------------

const mockGetUser = vi.fn()
const mockProfilesQuery = vi.fn()
const mockRpc = vi.fn()

vi.mock('@/lib/supabase/server', () => ({
  createClient: vi.fn(async () => ({
    auth: { getUser: mockGetUser },
    from: vi.fn((table: string) => {
      if (table === 'profiles') {
        return {
          select: vi.fn(() => ({
            eq: vi.fn(() => ({
              single: mockProfilesQuery,
            })),
          })),
        }
      }
      return {}
    }),
  })),
  createServiceRoleClient: vi.fn(() => ({
    rpc: mockRpc,
  })),
}))

// ---------------------------------------------------------------------------
// Mock rate limit
// ---------------------------------------------------------------------------

vi.mock('@/lib/rate-limit', () => ({
  authedRatelimit: { limit: vi.fn(async () => ({ success: true })) },
  adminExportRatelimit: { limit: vi.fn(async () => ({ success: true })) },
}))

vi.mock('@/lib/rate-limit/get-client-ip', () => ({
  getClientIp: vi.fn(() => '127.0.0.1'),
}))

// ---------------------------------------------------------------------------
// Mock audit log
// ---------------------------------------------------------------------------

const mockLogAuditAction = vi.fn(async () => undefined)
vi.mock('@/lib/audit', () => ({
  logAuditAction: mockLogAuditAction,
}))

// ---------------------------------------------------------------------------
// Mock logger
// ---------------------------------------------------------------------------

vi.mock('@/lib/logger', () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}))

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function makeRequest(body: unknown, headers: Record<string, string> = {}): NextRequest {
  return new NextRequest('http://localhost/api/admin/tax-oss-export', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...headers },
    body: JSON.stringify(body),
  })
}

const ADMIN_USER_ID = 'admin-user-s19-001'
const TARGET_STUDIO_ID = '11111111-1111-4111-8111-111111111111'

function setupAuthAdmin(): void {
  mockGetUser.mockResolvedValue({ data: { user: { id: ADMIN_USER_ID } }, error: null })
  mockProfilesQuery.mockResolvedValue({ data: { is_platform_admin: true }, error: null })
}

function setupAuthNonAdmin(): void {
  mockGetUser.mockResolvedValue({ data: { user: { id: 'regular-user-001' } }, error: null })
  mockProfilesQuery.mockResolvedValue({ data: { is_platform_admin: false }, error: null })
}

function setupAuthNone(): void {
  mockGetUser.mockResolvedValue({ data: { user: null }, error: null })
}

function makeOssResult(overrides: Partial<TaxOssQuarterlyExportResult> = {}): TaxOssQuarterlyExportResult {
  return {
    studio_id: TARGET_STUDIO_ID,
    period: '2026-Q1',
    jurisdictions: [
      {
        jurisdiction: 'EU-DE',
        amount_collected_cents: 10000,
        amount_remitted_cents: 5000,
        amount_outstanding_cents: 5000,
        registration_status: 'active',
      },
      {
        jurisdiction: 'EU-FR',
        amount_collected_cents: 8000,
        amount_remitted_cents: 0,
        amount_outstanding_cents: 8000,
        registration_status: null,
      },
    ],
    total_eu_collected_cents: 18000,
    total_eu_outstanding_cents: 13000,
    ...overrides,
  }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('POST /api/admin/tax-oss-export', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    mockRpc.mockResolvedValue({ data: makeOssResult(), error: null })
  })

  it('no auth → 401', async () => {
    setupAuthNone()
    const { POST } = await import('@/app/api/admin/tax-oss-export/route')

    const req = makeRequest({ studioId: TARGET_STUDIO_ID, year: 2026, quarter: 1 })
    const res = await POST(req)

    expect(res.status).toBe(401)
    const body = await res.json()
    expect(body.error).toBeTruthy()
  })

  it('authenticated non-admin → 403', async () => {
    setupAuthNonAdmin()
    const { POST } = await import('@/app/api/admin/tax-oss-export/route')

    const req = makeRequest({ studioId: TARGET_STUDIO_ID, year: 2026, quarter: 1 })
    const res = await POST(req)

    expect(res.status).toBe(403)
    const body = await res.json()
    expect(body.error).toBeTruthy()
  })

  it('missing year or quarter → 400', async () => {
    setupAuthAdmin()
    const { POST } = await import('@/app/api/admin/tax-oss-export/route')

    // Missing year
    const resNoYear = await POST(makeRequest({ studioId: TARGET_STUDIO_ID, quarter: 1 }))
    expect(resNoYear.status).toBe(400)

    // Missing quarter
    const resNoQuarter = await POST(makeRequest({ studioId: TARGET_STUDIO_ID, year: 2026 }))
    expect(resNoQuarter.status).toBe(400)

    // Missing studioId
    const resNoStudio = await POST(makeRequest({ year: 2026, quarter: 1 }))
    expect(resNoStudio.status).toBe(400)
  })

  it('happy path: 200, Content-Type text/csv, Content-Disposition with filename, CSV header + rows + TOTAL footer', async () => {
    setupAuthAdmin()
    const { POST } = await import('@/app/api/admin/tax-oss-export/route')

    const req = makeRequest({ studioId: TARGET_STUDIO_ID, year: 2026, quarter: 1 })
    const res = await POST(req)

    expect(res.status).toBe(200)
    expect(res.headers.get('Content-Type')).toMatch(/text\/csv/)

    const disposition = res.headers.get('Content-Disposition') ?? ''
    expect(disposition).toMatch(/attachment/)
    expect(disposition).toMatch(/filename="oss-/)
    expect(disposition).toMatch(/\.csv"/)

    const csv = await res.text()

    // Must have CSV header row
    expect(csv).toContain('jurisdiction,amount_collected_cents,amount_remitted_cents,amount_outstanding_cents,registration_status')

    // Must have data rows for seeded jurisdictions
    expect(csv).toContain('EU-DE')
    expect(csv).toContain('EU-FR')

    // Must have TOTAL footer lines
    expect(csv).toContain('TOTAL_EU_COLLECTED')
    expect(csv).toContain('TOTAL_EU_OUTSTANDING')
    expect(csv).toContain('18000')
    expect(csv).toContain('13000')

    // RPC was called with correct args
    expect(mockRpc).toHaveBeenCalledOnce()
    expect(mockRpc.mock.calls[0]?.[0]).toBe(RPC.TAX_OSS_QUARTERLY_EXPORT)
    expect(mockRpc.mock.calls[0]?.[1]).toMatchObject({
      p_studio_id: TARGET_STUDIO_ID,
      p_year: 2026,
      p_quarter: 1,
    })
  })

  it('audit log called exactly once on happy path', async () => {
    setupAuthAdmin()
    const { POST } = await import('@/app/api/admin/tax-oss-export/route')

    const req = makeRequest({ studioId: TARGET_STUDIO_ID, year: 2026, quarter: 1 })
    await POST(req)

    expect(mockLogAuditAction).toHaveBeenCalledOnce()
    const [userId, action] = mockLogAuditAction.mock.calls[0] as [string, string]
    expect(userId).toBe(ADMIN_USER_ID)
    expect(action).toBe('admin_tax_oss_export')
  })
})

